impl SovereignGossip for HyperGossipModel {
    fn push_event(&mut self, track_id: u8, midi_event: MidiEvent) {
        let tick = self.clock.current_tick();
        let echo_cycle = self.echo_cycle;
        let marker = TemporalMarker {
            id: uuid::Uuid::new_v4(),
            track_id,
            tick,
            created_at: chrono::Utc::now(),
            echo_cycle,
        };

        self.buffer.push((track_id, midi_event, marker));
        self.emit_temporal_marker(marker);
    }

    fn emit_temporal_marker(&mut self, marker: TemporalMarker) {
        self.time_machine_tx.send(marker).ok();
    }
}

