};

const StabilityColor: Record<TemporalMarker['stability'], string> = {
  stable: 'rgba(0, 255, 180, 0.6)',
  metastable: 'rgba(255, 200, 0, 0.6)',
  chaotic: 'rgba(255, 80, 80, 0.8)',
};

function TemporalDriftPanel() {
  const [markers, setMarkers] = useState<TemporalMarker[]>([]);

  useEffect(() => {
    const evtSource = new EventSource('/api/temporal-stream');
    evtSource.onmessage = (e) => {
      const marker = JSON.parse(e.data) as TemporalMarker;
      setMarkers((prev) => [...prev.slice(-256), marker]);
    };
    return () => evtSource.close();
  }, []);

  return (
    <div className="glass-panel">
      {markers.map((m) => (
        <div
          key={m.id}
          className="drift-dot"
          style={{
            backgroundColor: StabilityColor[m.stability],
            transform: `translate3d(${m.echo_cycle % 50}px, ${m.tick % 50}px, 0)`,
          }}
        />
      ))}
    </div>
  );
}

