fn to_pb_marker(m: &TemporalMarker, stability: TemporalStability) -> PbTemporalMarker {
    PbTemporalMarker {
        id: m.id.to_string(),
        track_id: m.track_id as u32,
        tick: m.tick,
        created_at: m.created_at.timestamp_millis(),
        echo_cycle: m.echo_cycle,
        stability: match stability {
            TemporalStability::Stable => TemporalStabilityPb::STABLE.into(),
            TemporalStability::Chaotic => TemporalStabilityPb::CHAOTIC.into(),
            TemporalStability::Metastable => TemporalStabilityPb::METASTABLE.into(),
        },
    }
}

