import sovereignpb "your/module/internal/proto/sovereign/temporal"

func ToPbMarker(m TemporalMarker) *sovereignpb.TemporalMarker {
    return &sovereignpb.TemporalMarker{
        Id:         m.ID,
        TrackId:    uint32(m.TrackID),
        Tick:       m.Tick,
        CreatedAt:  m.CreatedAt.UnixMilli(),
        EchoCycle:  m.EchoCycle,
        Stability:  toPbStability(m.Stability),
    }
}

func toPbStability(s TemporalStability) sovereignpb.TemporalStability {
    switch s {
    case Stable:
        return sovereignpb.TemporalStability_STABLE
    case Chaotic:
        return sovereignpb.TemporalStability_CHAOTIC
    case Metastable:
        return sovereignpb.TemporalStability_METASTABLE
    default:
        return sovereignpb.TemporalStability_STABILITY_UNSPECIFIED
    }
}

